''','''/** Matches nothing; for a filter value that cannot select any row. */
const NO_ROWS: SQL = sql`0 = 1`;

/** Escapes `LIKE` wildcards so `q` is a literal substring. */
function likePattern(query: string): string {
  return `%${query.replace(/[\\\\%_]/g, (char) => `\\\\${char}`)}%`;
}

/** `archived`: live only by default, `true` mixes in, `"only"` archived alone. */
function archivePredicate(input: IssueFilterInput): SQL | undefined {
  if (input.includeArchived === ARCHIVED_ONLY) {
    return isNotNull(issues.archivedAt);
  }
  const scope: ArchiveScope = shouldFilterArchived({
    includeArchived: input.includeArchived === true,
  })
    ? {}
    : { includeArchived: true };
  return livePredicate(issues.archivedAt, scope);
}

/**
 * `status`: any-of, with the groups `open` / `closed` expanded to their
 * members. A list that names nothing known matches nothing.
 */
function statusPredicate(input: IssueFilterInput): SQL | undefined {
  if (input.status === undefined || input.status.length === 0) return undefined;
  const statuses = expandIssueStatuses(input.status);
  return statuses.length === 0 ? NO_ROWS : inArray(issues.status, [...statuses]);
}

/** `assignee`: `undefined` does not filter, `null` / `none` is unassigned. */
function assigneePredicate(input: IssueFilterInput): SQL | undefined {
  const assigneeId: string | null | undefined = input.assigneeId;
  if (assigneeId === undefined) return undefined;
  if (assigneeId === null || assigneeId === "none") {
    return isNull(issues.assigneeId);
  }
  return eq(issues.assigneeId, assigneeId);
}

/**
 * `due_before`: a calendar date includes that whole UTC day, a timestamp is a
 * strict upper bound. Issues without a due date never match. The stored value
 * is normalised to millisecond precision so the comparison is by instant.
 */
function dueBeforePredicate(input: IssueFilterInput): SQL | undefined {
  if (input.dueBefore === undefined) return undefined;
  const bound = dueBeforeBound(input.dueBefore);
  if (bound === null) return NO_ROWS;
  return and(
    isNotNull(issues.dueAt),
    sql`strftime('%Y-%m-%dT%H:%M:%fZ', ${issues.dueAt}) < ${bound}`,
  );
}

/** `label`: all-of — one membership test per distinct label. */
function labelPredicates(input: IssueFilterInput): readonly (SQL | undefined)[] {
  if (input.labelIds === undefined) return [];
  return [...new Set(input.labelIds)].map((labelId) =>
    inArray(
      issues.id,
      getDb()
        .select({ id: issueLabels.issueId })
        .from(issueLabels)
        .where(
          and(
            orgPredicate(issueLabels.orgId, input.orgId),
            eq(issueLabels.labelId, labelId),
          ),
        ),
    ),
  );
}

/** Builds the shared predicate list behind `listIssues` and its count. */
function issueFilters(input: IssueFilterInput): readonly SQL[] {
  return compact(
    orgPredicate(issues.orgId, input.orgId),
    archivePredicate(input),
    input.projectId === undefined
      ? undefined
      : eq(issues.projectId, input.projectId),
    statusPredicate(input),
    input.priority === undefined || input.priority.length === 0
      ? undefined
      : inArray(issues.priority, [...input.priority]),
    assigneePredicate(input),
    input.authorId === undefined
      ? undefined
      : eq(issues.authorId, input.authorId),
    dueBeforePredicate(input),
    input.query === undefined || input.query.length === 0
      ? undefined
      : or(
          sql`${issues.title} like ${likePattern(input.query)} escape '\\\\'`,
          sql`${issues.description} like ${likePattern(input.query)} escape '\\\\'`,
        ),
    ...labelPredicates(input),
  );
}
''')

