  cleanup = await useTemporaryDatabase();
  t = await createTenant("scratch");
  const mk = async (o: Record<string, unknown>) =>
    issueRepo.insertIssue(issueInput(t.org.id, t.project.id, o as never), t.userIds.owner, await issueRepo.nextIssueNumber(t.org.id, t.project.id));
  await mk({ title: "a", assigneeId: t.userIds.member, status: "todo", dueAt: "2026-03-10T00:00:00.000Z", labelIds: [L1, L2] });
  await mk({ title: "b", assigneeId: null, status: "done", dueAt: "2026-03-10T23:59:59Z", labelIds: [L1] });
  await mk({ title: "c", assigneeId: null, status: "in_review", dueAt: "2026-03-11T00:00:00.000Z", labelIds: [L2] });
  const d = await mk({ title: "d", assigneeId: t.userIds.member, status: "canceled" });
  await issueRepo.archiveIssue(t.org.id, d.id);
});
afterAll(() => cleanup());

async function run(qs: string, actor = t.actors.member) {
  const f = issueFilterSchema.parse({ orgId: t.org.id, ...parseIssueFilterParams(new URLSearchParams(qs)) });
  const page = await issueService.listIssues(actor, f);
  expect(page.total).toBe(page.items.length);
  return page.items.map((i) => i.title).sort().join("");
}
describe("scratch", () => {
