    expect(await run("assignee=me", t.actors.owner)).toBe("");
    expect(await run("author=me", t.actors.owner)).toBe("abc");
    expect(await run("assignee=none")).toBe("bc");
    expect(await run(`label=${L1},${L2}`)).toBe("a");
    expect(await run(`label=${L1}`)).toBe("ab");
    expect(await run("due_before=2026-03-10")).toBe("ab");
    expect(await run("due_before=2026-03-10T00:00:00Z")).toBe("");
    expect(await run("due_before=2026-03-10T00:00:00.001Z")).toBe("a");
    expect(await run("due_before=2026-03-11T09:00:00%2B09:00")).toBe("a");
    expect(await run("due_before=garbage")).toBe("abc");
    expect(await run("status=open")).toBe("ac");
    expect(await run("status=closed")).toBe("b");
    expect(await run("status=open,done")).toBe("abc");
    expect(await run("archived=1")).toBe("abcd");
    expect(await run("archived=only")).toBe("d");
    expect(await run("archived=only&status=open")).toBe("");
    const p = await issueRepo.listIssues({ orgId: t.org.id, status: ["open"], limit: 1 });
    expect([p.total, p.items.length]).toEqual([2, 1]);
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, status: ["nope"] }).success).toBe(false);
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, dueBefore: "2026-02-30" }).success).toBe(false);
    expect(exportIssuesSchema.parse({ orgId: t.org.id, status: ["open"] }).includeArchived).toBe(false);
    expect(issueFilterToParams(parseIssueFilterParams(new URLSearchParams("archived=only&assignee=me&due_before=2026-03-10&status=closed")))).toEqual({ archived: "only", assignee: "me", due_before: "2026-03-10", status: "done,canceled" });
  });
});
