  const f = issueFilterSchema.parse({ orgId: t.org.id, ...parseIssueFilterParams(new URLSearchParams(qs)) });
  const page = await issueService.listIssues(actor, f);
  expect(page.total).toBe(page.items.length);
  return page.items.map((i) => i.title).sort().join("");
}
